warp:
shader_body
{
vec2 _uv = uv;

    // sample previous frame
    ret = texture( sampler_fc_main, _uv ).xyz;


ret += max(
max(texture(sampler_main, _uv+vec2(1.5,0.0)*texsize.wz).xyz,texture(sampler_main, _uv-vec2(1.5,0.0)*texsize.wz).xyz),
max(texture(sampler_main, _uv+vec2(0.0,1.5)*texsize.wz).xyz,texture(sampler_main, _uv-vec2(0.0,1.5)*texsize.wz).xyz));
ret -= texture(sampler_main, _uv).xyz;
    // darken (decay) over time
ret = ret*.94-.003; //or try: ret -= 0.004;

}

comp:
shader_body
{
    //flexi's bump map effect

    vec2 d = texsize.zw*4.0; 
    vec3 dx = ( ((texture(sampler_blur1, uv + vec2(1.0,0.0)*d).xyz * scale1) + bias1) - ((texture(sampler_blur1, uv-vec2(1.0,0.0)*d).xyz * scale1) + bias1) ); 
    vec3 dy = ( ((texture(sampler_blur1, uv + vec2(0.0,1.0)*d).xyz * scale1) + bias1) - ((texture(sampler_blur1, uv-vec2(0.0,1.0)*d).xyz * scale1) + bias1) ); 
    vec2 light_pos = vec2(0.5,0.2); 
    vec3 col = vec3(4.0,4.0,4.0); 
    float c = 4.0; 
    float dd = 16.0; 
    vec3 plastic; 
    plastic.x = col.x/(1.0+dd*pow(length( uv - vec2(dx.x,dy.x)*c - light_pos),0.5)); 
    plastic.y = col.y/(1.0+dd*pow(length( uv - vec2(dx.y,dy.y)*c - light_pos),0.5)); 
    plastic.z = col.z/(1.0+dd*pow(length( uv - vec2(dx.z,dy.z)*c - light_pos),0.5)); 

    ret = plastic*texture(sampler_main, uv).xyz; 
    ret *= 3.0;

ret.xy = vec2(0.0);
ret.x += mix(mix(0.0,2.0,mix(0.0,ret.z,uv.x)),mix(0.0,2.0,mix(0.0,ret.z,1.0-uv.x)),uv.x);
ret.z += mix(0.0,.4,mix(0.0,ret.z,1.0-uv.y));



}
